typedef unsigned int size_t;
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

class my_alloc {
  union Obj { union Obj *free_list_link; char client_data[1]; };
  enum { ALIGN = 8, MAX_BYTES = 128, NFREELISTS = 16 };
  static Obj *free_list[NFREELISTS];
  static size_t freelist_index(size_t bytes) {
    return ((bytes + ALIGN - 1) / ALIGN - 1);
  }
  static size_t round_up(size_t bytes) {
    return ((bytes + ALIGN - 1) & ~(ALIGN - 1));
  }
public:
  static void *refill(size_t);
  static void *oom_malloc(size_t);
  static void *allocate(size_t n) {
    if (n > MAX_BYTES) {
      void *result = arch_malloc(n, __FILE__, 0);
      return result ? result : oom_malloc(n);
    }
    Obj **list = free_list + freelist_index(n);
    Obj *result = *list;
    if (!result)
      return refill(round_up(n));
    *list = result->free_list_link;
    return result;
  }
  static void deallocate(void *p, size_t n) {
    if (n > MAX_BYTES)
      arch_free(p);
    else {
      Obj **list = free_list + freelist_index(n);
      Obj *q = (Obj *)p;
      q->free_list_link = *list;
      *list = q;
    }
  }
};

template<class T> class my_allocator {
public:
  T *allocate(size_t n, const void * = 0) {
    return n ? (T *)my_alloc::allocate(n * sizeof(T)) : 0;
  }
  void deallocate(T *p, size_t n) {
    my_alloc::deallocate(p, n * sizeof(T));
  }
};

typedef float rational_t;
typedef float time_value_t;

class vector3d {
public:
  typedef rational_t T;
  T x, y, z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d& operator=(const vector3d& v) {
    x = v.x; y = v.y; z = v.z; return *this;
  }
};

class particle_generator;
class particle;

class particle_force {
public:
  enum force_flavor_t {
    CONSTANT,
    RESISTANCE,
    TOWARDS_POINT,
  };
  particle_force() {}
  particle_force(force_flavor_t _flavor,
                 const vector3d& _multipurpose,
                 rational_t _delta_speed,
                 rational_t _terminal_speed)
    : flavor(_flavor),
      multipurpose(_multipurpose),
      delta_speed(_delta_speed),
      terminal_speed(_terminal_speed),
      recip_terminal_speed(1 / _terminal_speed) {}
  vector3d get_new_v(const particle&, particle_generator&, time_value_t);

  force_flavor_t flavor;
  vector3d multipurpose;
  vector3d utility;
  rational_t delta_speed;
  rational_t terminal_speed;
  rational_t recip_terminal_speed;
};

extern "C" particle_force *__particle_force_uninitialized_copy(
    const particle_force *, const particle_force *, particle_force *, int)
  __asm__("__uninitialized_copy_aux__H2ZPC14particle_forceZP14particle_force_X01X01X11G12__false_type_X11");

inline particle_force *uninitialized_copy(
    const particle_force *first,
    const particle_force *last,
    particle_force *result) {
  return __particle_force_uninitialized_copy(first, last, result, 0);
}

inline particle_force *copy(
    const particle_force *first,
    const particle_force *last,
    particle_force *result) {
  while (first != last) {
    *result = *first;
    ++first;
    ++result;
  }
  return result;
}

template<class T> inline void destroy(T *first, T *last) {
  while (first != last) {
    first->~T();
    ++first;
  }
}

template<class T, class Alloc> class vector {
protected:
  T *_M_start;
  T *_M_finish;
  T *_M_end_of_storage;
  Alloc allocator;
  T *_M_allocate(size_t n) {
    return n ? allocator.allocate(n) : 0;
  }
  void _M_deallocate(T *p, size_t n) {
    if (p) allocator.deallocate(p, n);
  }
  T *_M_allocate_and_copy(size_t n, const T *first, const T *last) {
    T *result = _M_allocate(n);
    uninitialized_copy(first, last, result);
    return result;
  }
public:
  typedef T *iterator;
  typedef const T *const_iterator;
  typedef size_t size_type;
  iterator begin() { return _M_start; }
  const_iterator begin() const { return _M_start; }
  iterator end() { return _M_finish; }
  const_iterator end() const { return _M_finish; }
  size_type size() const { return _M_finish - _M_start; }
  size_type capacity() const { return _M_end_of_storage - _M_start; }
  vector& operator=(const vector&);
};

template<class T, class Alloc>
vector<T, Alloc>& vector<T, Alloc>::operator=(const vector<T, Alloc>& __x)
{
  if (&__x != this) {
    const size_type __xlen = __x.size();
    if (__xlen > capacity()) {
      iterator __tmp = _M_allocate_and_copy(__xlen, __x.begin(), __x.end());
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = __tmp;
      _M_end_of_storage = _M_start + __xlen;
    }
    else if (size() >= __xlen) {
      iterator __i = copy(__x.begin(), __x.end(), begin());
      destroy(__i, _M_finish);
    }
    else {
      copy(__x.begin(), __x.begin() + size(), _M_start);
      uninitialized_copy(__x.begin() + size(), __x.end(), _M_finish);
    }
    _M_finish = _M_start + __xlen;
  }
  return *this;
}

template vector<particle_force, my_allocator<particle_force> >&
vector<particle_force, my_allocator<particle_force> >::operator=(
    const vector<particle_force, my_allocator<particle_force> >&);
